const loaded=Model.restore();
let s=loaded.state||Model.fresh();
let layers=[],appError='',sheetError='',scrolls={},returnFocus=null;
let liveConnection={status:'loading',data:null,error:''},researchController=null,planController=null;
s.otherTrips=Array.isArray(s.otherTrips)?s.otherTrips:[];s.discovery=s.discovery||Discovery.initial();if(!loaded.state)s.form={...s.form,prompt:'',date:'',undated:true,arrival:'',returnTime:'',hotel:''};if(s.research?.status==='running')s.research.status='paused';
if(s.job?.status==='running')s.job.status='paused';
s.form.mode=cvTransportValue(s.form.mode);
seedRouteEvidence(s.trip);s.otherTrips.forEach(item=>seedRouteEvidence(item.trip));
s.screen='home';s.saveStatus=loaded.error?'failed':loaded.state?'saved':'empty';
if(loaded.error)appError=loaded.error;
function isConnectionError(error){return ['NETWORK_ERROR','TIMEOUT','POLL_TIMEOUT','INVALID_RESPONSE'].includes(error.code);}
function liveHandleError(error){if(/LOGIN|AUTH|SESSION|CSRF/.test(error.code||''))liveConnection={status:'error',data:liveConnection.data,error:error.message};}
async function connectLive(){liveConnection={...liveConnection,status:'loading',error:''};render();try{const data=await LiveAPI.session();liveConnection={status:'ready',data,error:''};}catch(error){liveConnection={status:'error',data:null,error:error.message};}render();return liveConnection;}
async function ensureLiveReady(kind){if(liveConnection.status!=='ready')await connectLive();if(liveConnection.status!=='ready')throw new Error(liveConnection.error||'旅行服务尚未连接。');const data=liveConnection.data;if(data.connection?.loggedIn===false)throw new Error(data.connection.message||'攻略服务尚未登录，请完成服务端登录后重新检测连接。');if(data.capabilities?.[kind]===false)throw new Error(kind==='ai'?'AI 规划服务尚未配置，请先连接服务。':'攻略检索服务尚未就绪。');}
function liveConnectionMarkup(){const data=liveConnection.data;const loading=liveConnection.status==='loading';const needsLogin=data?.connection?.loggedIn===false;const text=loading?'正在检测旅行服务…':liveConnection.status==='error'?liveConnection.error:needsLogin?(data.connection.message||'攻略服务需要登录，请完成服务端登录后重新检测。'):'旅行服务已连接';return `<section class="live-connection ${liveConnection.status==='error'||needsLogin?'needs-attention':''}" aria-label="联网服务状态"><div><strong>${esc(text)}</strong>${liveConnection.status==='ready'&&!needsLogin?`<p>攻略${data.capabilities?.research===false?'未就绪':'可检索'} · AI${data.capabilities?.ai===false?'未就绪':'可规划'} · 地图${data.capabilities?.map?'可核对':'未连接'}</p>`:''}</div><button type="button" class="text-btn" data-action="reconnect-live" ${loading?'disabled':''}>${loading?'检测中':'重新检测'}</button></section>`;}
function liveSources(){return s.discovery.liveResearch?.sources||[];}
function liveSourceById(id){return [...(s.trip?.sources||[]),...liveSources()].find(source=>source.id===id);}
function liveSourceChips(ids,action='open-source'){return `<div class="source-chips live-source-chips">${(ids||[]).map(id=>{const source=liveSourceById(id);return `<button type="button" data-action="${action}" data-id="${esc(id)}">${icon('source',14)}<span>${esc(source?.title||'查看攻略来源')}</span></button>`;}).join('')}</div>`;}
function liveSourcesList(sources,action){return `<div class="source-list">${sources.map(source=>`<button type="button" class="source-row" data-action="${action}" data-id="${esc(source.id)}"><strong>${esc(source.title)}</strong><small>${esc(source.author||'作者未提供')} · ${esc(source.date||'日期未提供')} · ${Number(source.imageCount||source.images?.length||0)}张配图</small>${icon('arrow',16)}</button>`).join('')||'<p class="small-note">当前没有可用攻略来源。</p>'}</div>`;}
function liveSourceMarkup(source){const url=LiveAPI.sourceURL(source.url);return `<h3 class="source-heading">${esc(source.title)}</h3><p class="small-note">${esc(source.author||'作者未提供')} · ${esc(source.date||'日期未提供')}</p>${url?`<a class="live-original-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">查看小红书原帖${icon('link',15)}</a>`:''}<p class="sheet-copy">${esc(source.bodyExcerpt||source.excerpt||source.description||'该攻略未提供可展示的正文摘要。')}</p><p class="small-note">帖子内容作为旅行参考，营业、预约与路线仍需核对。</p><div class="live-source-gallery">${(source.images||[]).map(image=>liveImageMarkup(image,{alt:source.title+'的原帖攻略配图'})).join('')}</div>`;}
function liveEvidenceRecord(research=s.discovery.liveResearch){
 if(!research)return null;
 const sources=Array.isArray(research.sources)?research.sources:[],candidates=Array.isArray(research.candidates)?research.candidates:[],stats=research.stats||{};
 const text=(value,max=300)=>typeof value==='string'?value.slice(0,max):'';
 const count=key=>Number.isSafeInteger(stats[key])&&stats[key]>=0?stats[key]:null;
 const status=(value,allowed)=>allowed.includes(value)?value:'unknown';
 const date=typeof research.fetchedAt==='string'?new Date(research.fetchedAt):null;
 const sourceIds=new Set(sources.map(source=>source.id));
 return {
  fetchedAt:date&&!Number.isNaN(date.getTime())?date.toISOString():null,
  counts:{sourceCount:sources.length,candidateCount:candidates.length,imagesAvailable:count('imagesAvailable'),imagesRead:count('imagesRead'),matchedPlaceCount:count('matchedPlaceCount')},
  status:{retrieval:status(research.status?.retrieval,['live']),ai:status(research.status?.ai,['success']),map:status(research.status?.map,['success','partial','unavailable'])},
  sources:sources.map(source=>{const raw=LiveAPI.sourceURL(source.url);const url=raw?new URL(raw):null;if(url){url.search='';url.hash='';}return {title:text(source.title),author:text(source.author,100),date:text(source.date,40),url:url?.href||''};}),
  candidates:candidates.map(candidate=>{const proxyUrl=LiveAPI.imageURL(candidate.image);return {id:text(candidate.id,120),title:text(candidate.title,120),category:status(candidate.category,['sights','food','experiences']),sourceIds:(Array.isArray(candidate.sourceIds)?candidate.sourceIds:[]).filter(id=>sourceIds.has(id)).map(id=>text(id,120)),verificationStatus:status(candidate.verification?.status,['verified','unverified','ambiguous','not_found','unavailable']),image:proxyUrl?{proxyUrl,caption:'攻略配图，非地点实拍确认'}:null};})
 };
}
function liveEvidenceMarkup(){const record=liveEvidenceRecord();if(!record)return '';const labels={sourceCount:'来源攻略',candidateCount:'提取候选',imagesAvailable:'服务校验可读取的攻略图',imagesRead:'AI 已读取的攻略图',matchedPlaceCount:'地图已匹配地点'};return `<section class="live-evidence" aria-labelledby="live-evidence-title"><h2 id="live-evidence-title">联调记录</h2><p class="live-evidence-date">检索时间：${record.fetchedAt?`<time datetime="${esc(record.fetchedAt)}">${esc(new Date(record.fetchedAt).toLocaleString('zh-CN'))}</time>`:'未提供'}</p><dl>${Object.entries(record.counts).map(([key,value])=>`<div><dt>${labels[key]}</dt><dd data-evidence-count="${key}">${value===null?'未提供':value}</dd></div>`).join('')}</dl><p class="live-evidence-status">检索：${record.status.retrieval}<br>AI 提取：${record.status.ai}<br>地图核对：${record.status.map}</p><p class="live-evidence-note">服务校验与 AI 读图分别计数。攻略配图可关联多个候选，不作为地点实拍证明。</p><button type="button" class="text-btn" data-action="download-evidence">${icon('export',16)}导出联调记录</button></section>`;}
function exportLiveEvidence(){const record=liveEvidenceRecord();if(!record)return;const url=URL.createObjectURL(new Blob([JSON.stringify(record,null,2)],{type:'application/json;charset=utf-8'}));const anchor=document.createElement('a');anchor.href=url;anchor.download='MY_PLAN-联调记录.json';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const allNodes=()=>s.trip?.days.flatMap((day,dayIndex)=>day.stops.map(node=>({...node,dayIndex})))||[];
const findNode=id=>allNodes().find(node=>node.id===id);
const currentLayer=()=>layers[layers.length-1];
const discoveryCatalog=()=>Discovery.all(s.discovery);
const wishById=id=>discoveryCatalog().find(x=>x.id===id);
function wishResumeMarkup(){const count=Discovery.selected(s.discovery).length;return s.discovery.researched||count||s.research?`<section class="ready-result"><h2>${count?`想去清单已保留 ${count} 项`:'继续发现旅行内容'}</h2><p>选择清单与已生成的行程分开保存。</p><button class="text-btn" data-action="resume-discovery">${s.discovery.researched?'继续挑选':'继续整理攻略'}${icon('arrow',16)}</button></section>`:'';}
function tripSelectionMarkup(){return s.trip?.wishes?`<div class="dv-trip-selection"><span>根据你选的 ${s.trip.wishes.length} 项内容编排</span><button class="text-btn" data-action="review-wishes">查看原清单${icon('arrow',15)}</button></div>`:'';}
function restoreTripWishes(){if(!s.trip)return;s.discovery=Model.clone(s.trip.creationDiscovery||Discovery.initial());if(!s.trip.creationDiscovery){s.discovery.city=s.trip.city||s.trip.creationForm?.destination||s.trip.title.replace(/\d+日行程$/,'');s.discovery.liveResearch={id:s.trip.researchId||'',city:s.discovery.city,sources:Model.clone(s.trip.sources||[]),candidates:(s.trip.wishes||[]).map(wish=>({...wish,...(allNodes().find(n=>n.selectionId===wish.id)||{}),id:wish.id}))};s.discovery.selected=Object.fromEntries((s.trip.wishes||[]).map(item=>[item.id,{priority:item.priority||'want'}]));}s.discovery.researched=true;s.discovery.researchedFor=s.discovery.city;s.form={...Model.fresh().form,...s.trip.creationForm,days:s.trip.days.length,date:s.trip.date||'',undated:s.trip.undated,...s.trip.constraints};s.basketNotice='修改清单不会改变现有行程。重新编排会生成新草稿，旧稿保留。';persist();}
async function startResearch(){if(s.research?.status==='running')return route('search');const city=String(s.discovery.city||'').trim();if(!city||city.length>40){appError='请填写1～40字的目的地城市。';s.screen='search';return render();}try{await ensureLiveReady('research');}catch(error){appError=error.message;s.screen='search';return render();}const priorResearch=s.research?.jobId?Model.clone(s.research):null;const research={status:'running',city,progress:'正在提交攻略检索任务',jobId:'',error:''};s.research=research;appError='';s.screen='search';persist();render(true);researchController?.abort();researchController=new AbortController();try{const started=await LiveAPI.research(city,{signal:researchController.signal});if(s.research!==research)return;research.jobId=started.jobId;persist();await advanceResearch();}catch(error){if(s.research!==research||error.code==='ABORTED')return;if(error.code==='ACTIVE_JOB_CONFLICT'&&priorResearch){s.research={...priorResearch,status:'paused',resumable:true};appError=error.message+' 已保留原攻略任务，当前城市输入也已保存；可以继续查看原任务。';persist();return render(true);}research.status='failed';research.error=error.message;research.resumable=!!research.jobId&&isConnectionError(error);liveHandleError(error);persist();render();}}
async function advanceResearch(){const research=s.research;if(!research?.jobId||research.status!=='running')return;const controller=researchController||new AbortController();researchController=controller;try{const result=await LiveAPI.poll(research.jobId,{signal:controller.signal,onUpdate:job=>{if(s.research!==research)return;research.progress=String(job.progress||'正在检索与整理攻略');persist();render();}});if(s.research!==research)return;if(!result?.id||!Array.isArray(result.candidates)||!Array.isArray(result.sources))throw new Error('检索结果缺少候选或来源，请重新检索。');const changed=s.discovery.liveResearch?.id!==result.id;const inputCityChanged=String(s.discovery.city||'').trim()!==String(research.city||'').trim();s.discovery.liveResearch=result;if(!inputCityChanged)s.discovery.city=result.city||research.city;s.discovery.researched=true;s.discovery.researchedFor=result.city||research.city;if(changed){s.discovery.selected={};s.discovery.custom=[];s.discovery.query='';}research.status='done';research.progress='攻略已整理完成';research.resumable=false;if(s.screen==='search')s.screen='discover';persist();render(true);}catch(error){if(s.research!==research||error.code==='ABORTED')return;research.status='failed';research.error=error.message;research.resumable=isConnectionError(error);liveHandleError(error);persist();render();}}
function discoverySourceBody(id){const source=liveSources().find(x=>x.id===id);if(!source)return '<p>暂无此资料，请重新检索攻略。</p>';return liveSourceMarkup(source)+`<h3 class="section-title">这份攻略关联的候选</h3><div class="related-stops">${discoveryCatalog().filter(x=>(x.sourceIds||[]).includes(id)).map(x=>`<button data-action="wish-detail" data-id="${esc(x.id)}">${esc(x.title)}${icon('arrow',16)}</button>`).join('')}</div>`;}
const dayLabel=index=>`第${index+1}天`;
const attrs=id=>`data-id="${esc(id)}"`;
const input=(id,label,value,extra='')=>`<label class="field-label" for="${id}">${label}</label><input class="field" id="${id}" value="${esc(value??'')}" ${extra}>`;
function persist(){const result=Model.persist(s);s.saveStatus=result.ok?'saved':'failed';if(!result.ok)s.saveError=result.error;document.querySelectorAll('.save-status').forEach(el=>{el.textContent=result.ok?'已保存到本机':'保存失败 · 内容仍在';el.classList.toggle('failed',!result.ok);});return result.ok;}
function notice(text){s.lastMutation=text;persist();}
function route(screen){s.screen=screen;appError='';layers=[];sheetError='';persist();render(true);}
function openLayer(type,id,extra={}){if(!layers.length)returnFocus=describeFocus(document.activeElement);else currentLayer().scrollTop=document.querySelector('.sheet-scroll')?.scrollTop||0;layers.push({type,id,...extra});sheetError='';render();}
function describeFocus(el){return el?.dataset?.action?{action:el.dataset.action,id:el.dataset.id,value:el.dataset.value,index:el.dataset.index}:null;}
function findControl(ref){if(!ref)return null;return [...document.querySelectorAll('[data-action]')].find(el=>!el.disabled&&!el.closest('[inert]')&&el.dataset.action===ref.action&&['id','value','index'].every(key=>ref[key]===undefined||el.dataset[key]===ref[key]));}
function restoreFocus(){findControl(returnFocus)?.focus({preventScroll:true});returnFocus=null;}
function changedEditor(){const e=s.editor;if(!e)return false;const n=findNode(e.id);return e.isNew||!n||['title','time','notes','locked'].some(k=>String(e[k]??'')!==String(n[k]??''))||Number(e.duration)!==Number(n.duration);}
function closeLayer(force=false){const layer=currentLayer();if(layer?.type==='edit'&&s.editor&&changedEditor()&&!force){layer.discard=true;return render();}if(layer?.type==='edit'){s.editor=null;persist();}if(layer?.type==='ai-preview'){s.proposal=null;persist();}layers.pop();sheetError='';render();if(!layers.length)restoreFocus();}
function archiveCurrent(){if(!s.trip)return;s.otherTrips=s.otherTrips.filter(x=>x.trip?.id!==s.trip.id);s.otherTrips.unshift({trip:Model.clone(s.trip),editor:Model.clone(s.editor),history:Model.clone(s.history),lastMutation:s.lastMutation||''});}
function setTrip(trip){archiveCurrent();s.trip=trip;s.editor=null;s.proposal=null;s.history=[];s.selectedId=trip.days[0]?.stops[0]?.id||null;s.activeDay=0;s.tab='overview';s.view='list';s.job=null;s.screen='detail';s.lastMutation='';persist();render(true);}
function livePlanMatchesForm(trip,form){
 const undated=form.undated===true,days=Number(form.days),date=undated?null:form.date;
 if(!Array.isArray(trip.days)||trip.days.length!==days||trip.undated!==undated||(undated?!!trip.date:trip.date!==date))return false;
 if(!trip.constraints)return false;
 for(const key of ['arrival','returnTime','hotel'])if(String(trip.constraints[key]??'').trim()!==String(form[key]??'').trim())return false;
 return trip.days.every((day,index)=>{if(undated)return !day.date;const expected=new Date(`${date}T00:00:00Z`);if(Number.isNaN(expected.getTime()))return false;expected.setUTCDate(expected.getUTCDate()+index);return day.date===expected.toISOString().slice(0,10);});
}
async function startJob(){s.form.mode=cvTransportValue(s.form.mode);const error=Discovery.validatePlan(s.discovery);s.planUnplaced=[];if(error){appError=error;s.screen='create';return render();}if(s.job?.status==='running')return route('progress');try{await ensureLiveReady('ai');}catch(error){appError=error.message;return render();}const priorJob=s.job?.jobId?Model.clone(s.job):null;const capturedDiscovery=Model.clone(s.discovery);capturedDiscovery.city=capturedDiscovery.liveResearch?.city||capturedDiscovery.city;const job={status:'running',form:Model.clone(s.form),discovery:capturedDiscovery,jobId:'',progress:'正在提交已选清单',error:''};s.job=job;s.screen='progress';layers=[];appError='';persist();render(true);planController?.abort();planController=new AbortController();try{const started=await LiveAPI.plan(job.discovery.liveResearch.id,Discovery.selected(job.discovery).map(item=>({id:item.id,priority:item.priority})),job.form,{signal:planController.signal});if(s.job!==job)return;job.jobId=started.jobId;persist();await runJob();}catch(error){if(s.job!==job||error.code==='ABORTED')return;if(error.code==='ACTIVE_JOB_CONFLICT'&&priorJob){s.job={...priorJob,status:'paused',resumable:true};appError=error.message+' 已保留原规划任务，修改后的选择和条件也已保存；可以继续查看原任务。';persist();return render(true);}job.status='failed';job.error=error.message;job.resumable=!!job.jobId&&isConnectionError(error);liveHandleError(error);persist();render();}}
async function runJob(){const job=s.job;if(!job?.jobId||job.status!=='running')return;const controller=planController||new AbortController();planController=controller;try{const result=await LiveAPI.poll(job.jobId,{signal:controller.signal,onUpdate:remote=>{if(s.job!==job)return;job.progress=String(remote.progress||'AI 正在编排已选内容');persist();render();}});if(s.job!==job)return;if(result?.status==='needs_changes'){s.planUnplaced=result.unplaced||[];job.status='failed';job.resumable=false;job.error=result.message||'当前条件无法容纳全部选择，请调整后重试。';appError=job.error;s.screen='create';persist();return render(true);}if(result?.status!=='ready'||!result.trip?.days?.length)throw new Error('AI 返回的行程结构不完整，请重试。');const returned=result.trip.wishes||result.wishes;const expected=new Map(Discovery.selected(job.discovery).map(item=>[item.id,item.priority]));if(!Array.isArray(returned)||returned.length!==expected.size||new Set(returned.map(item=>item.id)).size!==expected.size||returned.some(item=>expected.get(item.id)!==item.priority))throw new Error('返回行程与所选清单或优先级不一致，已保留全部选择，请重新编排。');if(result.trip.researchId!=null&&result.trip.researchId!==job.discovery.liveResearch.id)throw new Error('返回行程与本次攻略检索不一致，已保留原行程与选择，请重新提交。');if(!livePlanMatchesForm(result.trip,job.form))throw new Error('返回行程的日期、天数或固定条件与本次请求不一致，已保留原行程与选择，请重新提交。');const trip=result.trip;trip.backendWarnings=Model.clone(Array.isArray(result.warnings)?result.warnings:[]);trip.backendStats=Model.clone(result.stats||{});trip.planJobId=job.jobId;trip.backendWarningsStale=false;trip.creationForm=Model.clone(job.form);trip.creationDiscovery=Model.clone(job.discovery);trip.researchId=job.discovery.liveResearch.id;trip.wishes=trip.wishes||result.wishes||Discovery.selected(job.discovery);trip.sources=trip.sources||job.discovery.liveResearch.sources;trip.budget=trip.budget||{stay:0,food:0,transport:0,tickets:0,misc:0};trip.preparation=trip.preparation||{umbrella:false,shoes:false,booking:false};trip.constraints=trip.constraints||{arrival:job.form.arrival,returnTime:job.form.returnTime,hotel:job.form.hotel};seedRouteEvidence(trip);if(s.screen==='progress'&&!layers.length)return setTrip(trip);if(!s.trip){s.trip=trip;s.history=[];s.job=null;}else{s.otherTrips.unshift({trip,editor:null,history:[],lastMutation:''});job.status='done';job.resultId=trip.id;}persist();render();}catch(error){if(s.job!==job||error.code==='ABORTED')return;job.status='failed';job.error=error.message;job.resumable=isConnectionError(error);liveHandleError(error);persist();render();}}
function startEditor(id,isNew=false){const editIndex=layers.findIndex(x=>x.type==='edit');if(s.editor){if(!isNew&&s.editor.id===id){if(editIndex>=0){layers=layers.slice(0,editIndex+1);return render();}return openLayer('edit',id);}if(changedEditor())return openLayer('edit-conflict',id,{isNew});s.editor=null;if(editIndex>=0)layers=[];}const n=findNode(id);if(!isNew&&!n)return;s.editor=isNew?{id:'',isNew:true,dayIndex:s.activeDay,title:'',time:freeTime(s.activeDay),duration:45,notes:'',locked:false,sourceIds:[]}:({...Model.clone(n),isNew:false});persist();openLayer('edit',id);}
function freeTime(index){const stops=s.trip.days[index].stops;for(let t=9*60;t<=22*60;t+=15)if(stops.every(n=>t+45<=Model.timeMinutes(n.time)||t>=Model.timeMinutes(n.time)+n.duration))return Model.formatTime(t);return '20:00';}
function mutation(result,text){if(!result.ok){sheetError=result.error;return render();}layers=[];sheetError='';notice(text);render();}
function routeEvidenceSignatures(trip){return (trip?.days||[]).map(day=>rvRouteSignature(trip,day));}
function seedRouteEvidence(trip){if(!trip)return;for(const day of trip.days||[])if(Array.isArray(day.legs)&&day.legs.length&&!day.routeEvidenceSignature)day.routeEvidenceSignature=rvRouteSignature(trip,day);}
function invalidateRouteEvidence(before,trip,forced=[]){let changed=false;for(const [index,day] of (trip?.days||[]).entries()){if(!forced.includes(index)&&before[index]===rvRouteSignature(trip,day))continue;day.legs=[];day.routeEvidenceSignature=null;day.routeEvidenceStale=true;day.routeDirty=true;for(const node of day.stops||[]){node.travelMinutes=null;node.travelStatus='unavailable';node.travelCheckedAt=null;}changed=true;}if(changed){trip.backendWarningsStale=true;trip.backendStatsStale=true;}return changed;}
function routeMutation(apply,text){const before=routeEvidenceSignatures(s.trip);const result=apply();if(result.ok)invalidateRouteEvidence(before,s.trip);return mutation(result,text);}
function sourceBody(id){const source=s.trip.sources.find(x=>x.id===id);if(!source)return '<p>当前来源不可用。</p>';return liveSourceMarkup(source)+`<h3 class="section-title">相关安排</h3><div class="related-stops">${allNodes().filter(n=>(n.sourceIds||[]).includes(id)).map(n=>`<button data-action="source-node" ${attrs(n.id)}><span>${esc(n.title)}<small>${dayLabel(n.dayIndex)} · ${esc(n.time)}</small></span>${icon('arrow',16)}</button>`).join('')}</div>`;}
function proposalBody(){const p=s.proposal;if(!p)return '<p>没有待查看的建议。</p>';return `<div class="soft-note">${esc(p.summary)}</div><p class="small-note">本地规则建议 · 应用前不会修改现有行程</p><div class="change-list">${p.changes.map(c=>`<article><span class="change-type">${c.type==='remove'?'移除可选项':'调整时间'}</span><h3>${esc(c.before.title)}</h3><p>${dayLabel(c.dayIndex)} · ${c.before.time} / ${c.before.duration}分钟 ${c.after?`${icon('arrow',13)} ${c.after.time} / ${c.after.duration}分钟`:'→ 留作自由休息'}</p><small>${esc(c.reason||'按本次要求提出建议')}</small></article>`).join('')}</div><h3 class="section-title">保持不变</h3><p class="sheet-copy">${p.preserved.length?p.preserved.map(esc).join('、'):'其他日期和未列出的安排保持不变。'}</p><p class="small-note">交通待重新核对；没有声称已计算节省的步行距离。</p>`;}
function sheetContent(layer){let title='',body='',footer='';const n=findNode(layer.id);
if(layer.type==='wish-detail'){const item=wishById(layer.id);if(!item)return{title:'候选已移除',body:'<p>可返回继续挑选。</p>',footer:''};const picked=!!s.discovery.selected[item.id];title=item.title;body=`${liveImageMarkup(item.image,{className:'live-sheet-image',alt:item.title+'的攻略配图'})}<p class="sheet-copy">${esc(item.description||item.notes||'由你补充的旅行内容。')}</p><div class="sheet-kv"><span>区域</span><strong>${esc(item.region||'待确定')}</strong></div><div class="sheet-kv"><span>停留参考</span><strong>${Number(item.duration)>0?esc(item.duration)+'分钟':'待确定'} · 未计算交通</strong></div>${item.category==='food'?'<div class="soft-note">先保留感兴趣的美食与餐饮地点，具体用餐安排可在排行程后再确认。</div>':''}${liveSourceChips(item.sourceIds||[],'open-discovery-source')}<p class="small-note">${esc(item.verification?.message||'攻略中的提及不代表营业、票务与路线已核验。')}</p>`;footer=`${button(picked?'从清单移除':item.category==='food'?'加入想吃清单':'加入想去清单','toggle-wish',{attrs:attrs(item.id)})}${button('继续挑选','close-sheet',{secondary:true})}`;}
if(layer.type==='discovery-source'){title='攻略依据';body=discoverySourceBody(layer.id);footer=button('返回继续挑选','close-sheet',{secondary:true});}
if(layer.type==='discovery-sources'){title='这次参考的攻略';body=`<p class="sheet-copy">本次检索获得${liveSources().length}篇攻略。配图保留原帖归属，未确认是候选地点实拍。</p>${liveSourcesList(liveSources(),'open-discovery-source')}`;}
if(layer.type==='add-wish'){title='补充一个想法';body=`${input('custom-wish-title','想去的地方／想吃的内容',layer.title||'','data-layer="title" maxlength="60" placeholder="例如：找一家喜欢的面馆"')}<label class="field-label" for="custom-wish-category">放在哪一类</label><select id="custom-wish-category" class="field" data-layer="category">${[['sights','想去'],['food','想吃'],['experiences','想体验']].map(([value,label])=>`<option value="${value}" ${layer.category===value?'selected':''}>${label}</option>`).join('')}</select>${input('custom-wish-duration','大约停留／分钟',layer.duration||60,'type="number" min="15" max="480" data-layer="duration"')}<p class="small-note">手动补充不会借用攻略出处或位置；首次 AI 编排暂不支持这些内容。内容会保留，生成行程后可手动添加。</p>`;footer=button('加入我的清单','commit-custom-wish');}
if(layer.type==='experience-location'){title='补充这项体验的地点';body=`<h3>${esc(n.title)}</h3><p class="sheet-copy">这里需要的是体验的具体地点。当前没有匹配茶馆、步行起终点的真实搜索结果，可以先手动记下，不会替换成无关景点。</p>${input('experience-place','地点名称或起终点',layer.place||'','data-layer="place" maxlength="100" placeholder="例如：已订茶馆的名称，或沿河步行起点"')}${liveSourceChips(n.sourceIds)}<p class="small-note">保存为手动地点，实际坐标和相邻交通仍待核对。原帖仅作为体验参考，地点由你指定。</p>`;footer=`${button('保存手动地点','commit-experience-place')}${button('先保留待定','close-sheet',{secondary:true})}`;}
if(layer.type==='edit-conflict'){title='还有一处修改未提交';body=`<p class="sheet-copy">“${esc(s.editor?.title||'新安排')}”的输入还在。继续原编辑，或明确放弃后再编辑另一站。</p>`;footer=`${button('继续原来的编辑','keep-original-edit')}${button('放弃原修改，编辑这一站','switch-edit',{secondary:true})}`;}
if(layer.type==='node'){if(!n)return{title:'安排已变更',body:'<p>这项安排已经移除，可以从下方撤销。</p>',footer:''};title=n.title;body=`${liveImageMarkup(n.liveImage||n.image,{className:'live-sheet-image',alt:n.title+'的攻略配图'})}<p class="sheet-copy">${esc(n.notes||'可以添加自己的备注。')}</p><div class="sheet-kv"><span>安排</span><strong>${dayLabel(n.dayIndex)} · ${esc(n.time)} · ${esc(n.duration)}分钟</strong></div><div class="sheet-kv"><span>位置状态</span><strong>${rvLocationLabel(n)}</strong></div>${n.locked?'<div class="soft-note">这是固定安排。调整建议会保留；你可以主动编辑。</div>':''}${liveSourceChips(n.sourceIds||[])}${n.sourceIds?.length?'':'<p class="small-note">未附加攻略出处。</p>'}<div class="sheet-actions">${button('编辑这一站','edit',{attrs:attrs(n.id)})}${button(n.locationStatus==='pending'?(n.kind==='meal'?'补充用餐地点':'补充具体地点'):'手动更换地点','confirm',{secondary:true,attrs:attrs(n.id)})}${rvHasLocation(n)?button('在位置示意图中查看','locate',{secondary:true,attrs:attrs(n.id)}):''}</div>`;}
if(layer.type==='edit'){const e=s.editor;if(!e)return{title:'没有未完成修改',body:'',footer:''};title=e.isNew?'添加一个安排':'编辑这一站';body=`${layer.discard?`<div class="error-note"><p>这处修改尚未提交，是否放弃？</p><div class="inline-actions">${button('继续编辑','keep-edit',{secondary:true})}${button('放弃修改','discard-edit')}</div></div>`:''}${input('edit-title','安排名称（仅修改显示文字）',e.title,'data-edit="title" maxlength="80"')}<p class="small-note">更换景点或门店请使用“替换实际地点”，避免只改名称却保留旧位置。</p><div class="field-pair"><div>${input('edit-time','开始时间',e.time,'type="time" data-edit="time"')}</div><div>${input('edit-duration','停留／分钟',e.duration,'type="number" min="1" max="720" data-edit="duration"')}</div></div><label class="field-label" for="edit-notes">备注</label><textarea class="field" id="edit-notes" data-edit="notes" rows="3" maxlength="500">${esc(e.notes||'')}</textarea><label class="check-field"><input type="checkbox" data-edit="locked" ${e.locked?'checked':''}>固定时间，AI调整时保留</label>${liveSourceChips(e.sourceIds||[])}<p class="small-note">当前输入会保留到本机；查看出处后返回可继续。点“保存修改”后才更新行程。</p>`;footer=button('保存修改','commit-editor');}
if(layer.type==='source'){title='攻略依据';body=sourceBody(layer.id);footer=button(layers.length>1?'返回刚才的操作':'返回行程','close-sheet',{secondary:true});}
if(layer.type==='sources'){title='参考攻略';body=`<p class="sheet-copy">这些攻略来自本次检索，点击可查看引用与原帖。营业、预约与路线仍需核对。</p>${liveSourcesList(s.trip.sources||[],'open-source')}`;}
if(layer.type==='node-menu'){title=n?.title||'安排操作';body=`<div class="menu-rows"><button data-action="edit" ${attrs(layer.id)}>${icon('edit',19)}编辑时间与备注</button><button data-action="confirm" ${attrs(layer.id)}>${icon('pin',19)}替换实际地点</button><button data-action="move" ${attrs(layer.id)} ${n?.locked?'disabled':''}>${icon('calendar',19)}移动到另一天／调整顺序</button><button data-action="remove" ${attrs(layer.id)} ${n?.locked?'disabled':''}>${icon('minus',19)}移除这一站</button></div>${n?.locked?'<p class="small-note">固定安排先在编辑中取消固定，才能移动或移除。</p>':'<p class="small-note">移除、移动后可以撤销，其他固定安排保持不变。</p>'}`;}
if(layer.type==='move'){title='移动与调整顺序';body=`<h3>${esc(n.title)}</h3><label class="field-label" for="move-day">放在哪一天</label><select class="field" id="move-day" data-layer="targetDay">${s.trip.days.map((d,i)=>`<option value="${i}" ${Number(layer.targetDay)===i?'selected':''}>${dayLabel(i)} · ${esc(d.name)}</option>`).join('')}</select>${input('move-time','新的开始时间',layer.targetTime,'type="time" data-layer="targetTime"')}<p class="small-note">按开始时间排序。只移动这一站；固定安排不会顺延。时间冲突时会指出具体安排。</p>`;footer=button('移动并保存','commit-move');}
if(layer.type==='confirm'){title='手动补充具体地点';body=`<p class="sheet-copy">${esc(n.title)}</p><p class="small-note">可以记下实际地点名称。这里不会提供未经检索的门店或坐标。</p>${input('manual-place','地点或门店名称',layer.place||'','data-layer="place" maxlength="100"')}${liveSourceChips(n.sourceIds||[])}<p class="small-note">更换地点后将清除旧坐标、配图与来源关联，原行程可撤销恢复。</p>`;footer=`${button('保存手动地点','commit-manual-place')}${button('先保留原安排','close-sheet',{secondary:true})}`;}
if(layer.type==='ai'){title='规则调整建议';body=`<p class="sheet-copy">先说清改哪部分，再查看具体变化。固定项和手动修改默认保留。</p><label class="field-label" for="ai-scope">调整范围</label><select id="ai-scope" class="field" data-layer="scope"><option value="day" ${layer.scope==='day'?'selected':''}>${dayLabel(s.activeDay)}全部可调整项</option><option value="remaining" ${layer.scope==='remaining'?'selected':''}>${dayLabel(s.activeDay)}剩余安排</option><option value="trip" ${layer.scope==='trip'?'selected':''}>整趟行程</option></select><label class="field-label" for="ai-prompt">想怎么调整</label><textarea class="field" id="ai-prompt" rows="3" data-layer="prompt" placeholder="例如：少走一点，留出休息时间">${esc(layer.prompt||'')}</textarea><div class="quick-choices"><button data-action="ai-preset" data-value="少走一点，留出休息时间">少走一点</button><button data-action="ai-preset" data-value="晚出发一小时">晚出发一小时</button></div><p class="small-note">此处使用本地规则，支持上述两种意图；不会发起新的 AI 请求。“剩余安排”以当前选中站及其后的安排为范围。</p>`;footer=button('生成变更预览','preview-ai');}
if(layer.type==='ai-preview'){title='查看建议变化';body=proposalBody();footer=`${button('应用这些变化','apply-ai')}${button('放弃建议','discard-ai',{secondary:true})}`;}
if(layer.type==='budget'){title='整趟预计预算';body=`<p class="small-note">人民币 · 自填预算 · 修改后点保存才生效</p>${[['stay','住宿'],['food','餐饮'],['transport','交通'],['tickets','门票与预约'],['misc','其他']].map(([key,label])=>`<div class="budget-input-row"><label for="budget-${key}">${label}</label><input id="budget-${key}" class="field" type="number" inputmode="numeric" min="0" max="100000" data-budget="${key}" value="${layer.budget[key]}"></div>`).join('')}<p class="small-note">门票为0表示待核对，不代表免费。尚未接入报价。</p><p class="budget-sum">合计 <strong id="budget-sum">${money(Object.values(layer.budget).reduce((a,b)=>a+Number(b||0),0))}</strong></p>`;footer=button('保存修改','commit-budget');}
if(layer.type==='weather'){title='天气与准备';body=`<div class="soft-note"><h3>${s.trip.undated?'日期未定，先准备随身物品':'临近出发再核对天气'}</h3><p>当前没有接入实时预报，行程不会据此自动更换景点。</p></div><h3 class="section-title">出行准备</h3><div class="prep-list">${[['umbrella','便携雨具'],['shoes','舒适步行鞋'],['booking','证件与预约信息']].map(([key,label])=>`<button data-action="prep" data-key="${key}" aria-pressed="${s.trip.preparation[key]}"><span class="check-box">${s.trip.preparation[key]?icon('check',15):''}</span>${label}</button>`).join('')}</div><p class="small-note">勾选即时保存；在本机重开会保留。</p>`;}
if(layer.type==='conditions'){title='这趟旅行的条件';body=`<div class="condition-details"><p><span>日期</span><strong>${s.trip.undated?'暂未确定':esc(s.trip.date)}</strong></p><p><span>天数</span><strong>${s.trip.days.length}天</strong></p><p><span>到达</span><strong>${esc(s.trip.constraints.arrival||'未指定')}</strong></p><p><span>返程</span><strong>${esc(s.trip.constraints.returnTime||'未指定')}</strong></p><p><span>住宿</span><strong>${esc(s.trip.constraints.hotel||'未指定')}</strong></p></div><p class="small-note">到达、返程、住宿已作为固定安排，可在对应站点主动编辑。整体改日期或天数，请新建一份草稿，旧稿保留。</p>`;footer=button('按新条件再建一份','new-from-trip',{secondary:true});}
if(layer.type==='menu'){title='行程工具';body=`<div class="menu-rows"><button data-action="conditions">${icon('calendar',20)}查看旅行条件</button><button data-action="sources">${icon('source',20)}参考攻略</button><button data-action="budget">${icon('budget',20)}预计预算</button><button data-action="weather">${icon('weather',20)}天气与准备</button><button data-action="export">${icon('export',20)}导出当前行程</button><button data-action="undo" ${s.history.length?'':'disabled'}>${icon('back',20)}撤销上一次修改</button></div>`;}
if(layer.type==='export'){title='导出当前已提交的行程';body=`<p class="sheet-copy">导出到本机，保留待定标记、出处、预算和准备清单。未提交的编辑仍保留在编辑草稿中。</p><div class="export-list"><button data-action="download-txt">${icon('source',22)}<span><strong>可读行程清单</strong><small>TXT，适合直接阅读</small></span>${icon('arrow',17)}</button><button data-action="download-json">${icon('export',22)}<span><strong>完整结构数据</strong><small>JSON，含预算和准备状态</small></span>${icon('arrow',17)}</button></div>`;}
if(layer.type==='node'&&n?.locationNote)body+=`<p class="small-note">${esc(n.locationNote)}</p>`;
return{title,body,footer};}
function sheetMarkup(){if(!layers.length)return '';const {title,body,footer}=sheetContent(currentLayer());return `<div class="sheet-layer"><button class="sheet-scrim" tabindex="-1" data-action="close-sheet" aria-label="关闭面板"></button><section class="sheet" role="dialog" aria-modal="true" tabindex="-1" aria-labelledby="sheet-title"><div class="sheet-handle" aria-hidden="true"></div><header class="sheet-header"><h2 id="sheet-title">${esc(title)}</h2><button class="icon-btn" data-action="close-sheet" aria-label="${layers.length>1?'返回上一层':'关闭面板'}">${icon(layers.length>1?'back':'close',21)}</button></header><div class="sheet-scroll">${sheetError?`<div class="error-note" role="alert">${esc(sheetError)}</div>`:''}${body}</div>${footer?`<footer class="sheet-footer">${footer}</footer>`:''}</section></div>`;}
function readyMarkup(){return s.job?.status==='done'?`<section class="ready-result"><h2>新的行程草稿已整理好</h2><p>刚才的修改保持原样，准备好后再打开新稿。</p><button class="text-btn" data-action="open-archive" ${attrs(s.job.resultId)}>查看新草稿${icon('arrow',16)}</button></section>`:'';}
function archiveMarkup(){return s.otherTrips.length?`<section class="other-trips"><h2>其他已保存的行程</h2>${s.otherTrips.map(x=>`<button data-action="open-archive" ${attrs(x.trip.id)}><span><strong>${esc(x.trip.title)}</strong><small>${x.trip.undated?'日期未定':esc(x.trip.date)} · ${x.trip.days.length}天</small></span>${icon('arrow',16)}</button>`).join('')}</section>`:'';}
function shell(){
 const titles={home:'旅行行程',search:'发现城市',discover:'挑选旅行内容',basket:'我的想去清单',create:'补充出行条件',progress:'编排行程',detail:'旅行详情'};
 const body={home:()=>homeBody(s)+readyMarkup()+archiveMarkup(),search:()=>cityBody(s),discover:()=>discoveryBody(s),basket:()=>(s.basketNotice?`<div class="soft-note">${esc(s.basketNotice)}</div>`:'')+basketBody(s),create:()=>createBody(s),progress:()=>progressBody(s),detail:()=>s.trip?tripSelectionMarkup()+resultBody(s):homeBody(s)}[s.screen]();
 const researchRunning=s.research?.status==='running',researchPaused=s.research?.status==='paused';
 const controls=s.screen==='search'?button(researchRunning?'正在检索攻略':researchPaused?'继续查看攻略任务':'搜索当地攻略',researchPaused?'resume-research':'search-city',{disabled:researchRunning||liveConnection.status==='loading'}):s.screen==='discover'?button(`查看想去清单（${Discovery.selected(s.discovery).length}）`,'to-basket'):s.screen==='basket'?button('下一步，补充出行条件','to-conditions',{disabled:!Discovery.selected(s.discovery).length}):s.screen==='create'?button('让 AI 安排已选内容','generate',{disabled:s.job?.status==='running'}):s.screen==='detail'&&s.lastMutation?`<div class="undo-bar"><span role="status">${esc(s.lastMutation)}</span><button class="text-btn" data-action="undo" ${s.history.length?'':'disabled'}>撤销</button><button class="icon-btn" data-action="dismiss-notice" aria-label="收起操作提示">${icon('close',16)}</button></div>`:'';
 return `<div class="workbench v2-workbench v3-workbench"><aside class="workbench-info"><h1>先选喜欢的<br>再安排行程</h1><p>检索当地攻略，挑选想去和想吃的，再交给 AI 编排。</p><ol><li>输入城市，检索攻略</li><li>浏览景点、美食和体验</li><li>加入清单，标记必选</li><li>补充日期、酒店等条件</li><li>AI 编排已选内容，排不下先说明</li></ol><h2>显示设置</h2><div class="theme-options"><button data-action="theme" data-value="light" aria-pressed="${s.theme==='light'}">暖白</button><button data-action="theme" data-value="dark" aria-pressed="${s.theme==='dark'}">深色</button></div><button class="text-btn" data-action="reopen">重新打开本机草稿</button><p class="workbench-note">检索与 AI 规划需要连接本机旅行服务和网络。选择清单、编辑和草稿保存在本浏览器；本页面不接入 Android。</p></aside><div class="device" data-theme="${s.theme}"><div class="statusbar"><span>MY PLAN</span><span>${icon('wifi',13)}${icon('battery',17)}</span></div><header class="appbar"><button class="icon-btn" data-action="home" aria-label="返回我的行程" ${s.screen==='home'?'disabled':''}>${icon('back',23)}</button><strong>${titles[s.screen]}</strong>${s.screen==='detail'?`<button class="icon-btn" data-action="menu" aria-label="打开行程工具">${icon('more',22)}</button>`:'<span></span>'}</header><div class="save-row"><span class="save-status ${s.saveStatus==='failed'?'failed':''}" role="status">${s.saveStatus==='failed'?'保存失败 · 内容仍在':s.saveStatus==='saved'?'已保存到本机':'本机草稿'}</span>${s.saveStatus==='failed'?'<button class="text-btn" data-action="retry-save">重试保存</button>':'<span>联网旅行规划</span>'}</div>${s.screen==='detail'?`<nav class="main-tabs" role="tablist" aria-label="旅行详情分区">${[['overview','概览'],['itinerary','行程']].map(([id,label])=>`<button id="tab-${id}" data-action="tab" data-value="${id}" role="tab" tabindex="${s.tab===id?0:-1}" aria-selected="${s.tab===id}" aria-controls="phone-scroll">${label}</button>`).join('')}</nav>`:''}<main id="phone-scroll" class="phone-scroll" ${s.screen==='detail'?`role="tabpanel" aria-labelledby="tab-${s.tab}" tabindex="0"`:''}>${liveConnectionMarkup()}${appError?`<div class="error-note" role="alert">${esc(appError)}</div>`:''}${body}</main><footer class="phone-footer ${controls?'':'empty-footer'}">${controls}</footer><div class="home-indicator"><span></span></div>${sheetMarkup()}</div><aside class="design-notes"><h2>从真实攻略到自己的旅行</h2><ul><li>候选来自本次检索</li><li>原帖标题、作者与配图可追溯</li><li>攻略配图不作为地点实拍证明</li><li>选择后才提交给 AI 编排</li><li>未排入内容会明确说明</li><li>草稿可编辑、归档和撤销</li></ul><p>地图仅展示已返回坐标的位置分布；实际道路、营业、预约和交通仍需核对。首次 AI 编排暂不支持手动补充项，生成后可在行程中添加。</p>${liveEvidenceMarkup()}</aside></div>`;
}
function scrollKey(){return `${s.screen}-${s.tab}-${s.view}-${s.activeDay}`;}
let oldScrollKey=null,renderedScreen=null;
function render(reset=false){
 const oldScroll=document.querySelector('#phone-scroll');if(oldScroll&&oldScrollKey)scrolls[oldScrollKey]=oldScroll.scrollTop;
 const oldTrack=document.querySelector('.rv-photo-track');if(oldTrack?.firstElementChild)s.carouselIndex=Math.round(oldTrack.scrollLeft/(oldTrack.firstElementChild.offsetWidth+12));
 const activeId=document.activeElement?.id,activeControl=describeFocus(document.activeElement),sheetScroll=document.querySelector('.sheet-scroll')?.scrollTop||0,oldType=document.querySelector('.sheet')?.dataset.type;
 document.getElementById('app').innerHTML=shell();liveBindImages(document.getElementById('app'));oldScrollKey=scrollKey();const scroll=document.querySelector('#phone-scroll');scroll.scrollTop=reset?0:scrolls[oldScrollKey]||0;
 const track=document.querySelector('.rv-photo-track');if(track?.firstElementChild){track.scrollLeft=(s.carouselIndex||0)*(track.firstElementChild.offsetWidth+12);track.addEventListener('scroll',()=>{s.carouselIndex=Math.round(track.scrollLeft/(track.firstElementChild.offsetWidth+12));const count=document.getElementById('photo-count');if(count)count.textContent=`${Math.min(track.children.length,s.carouselIndex+1)}/${track.children.length}`;},{passive:true});}
 if(s.focusNode){const row=document.getElementById('node-'+s.focusNode);if(row)scroll.scrollTop=Math.max(0,row.getBoundingClientRect().top-scroll.getBoundingClientRect().top+scroll.scrollTop-14);s.focusNode=null;}
 document.querySelectorAll('.workbench-info,.design-notes,.device > :not(.sheet-layer)').forEach(el=>{el.inert=!!layers.length;});document.documentElement.classList.toggle('v2-modal',!!layers.length);document.documentElement.style.overflow=layers.length?'clip':'';document.body.style.overflow=layers.length?'clip':'';if(layers.length){document.documentElement.scrollTop=0;document.body.scrollTop=0;}
 if(layers.length){if(matchMedia('(max-width:680px)').matches)window.scrollTo(0,0);const sheet=document.querySelector('.sheet');sheet.dataset.type=currentLayer().type;document.querySelector('.sheet-scroll').scrollTop=oldType===currentLayer().type?sheetScroll:currentLayer().scrollTop||0;const focusId=oldType===currentLayer().type?activeId:currentLayer().focus?.id;const retained=focusId&&document.getElementById(focusId);(retained&&sheet.contains(retained)?retained:sheet.querySelector('.sheet-header button')).focus({preventScroll:true});const selection=currentLayer().focus;if(retained&&selection&&typeof retained.setSelectionRange==='function'&&['text','textarea'].includes(retained.type)){retained.setSelectionRange(selection.start||0,selection.end||0);}}
 if(!layers.length){let target=renderedScreen===s.screen?(findControl(activeControl)||(activeId&&document.getElementById(activeId))):null;if(!target){target=document.querySelector('#phone-scroll h1');if(target)target.tabIndex=-1;}target?.focus({preventScroll:true});}renderedScreen=s.screen;
 if(reset&&matchMedia('(max-width:680px)').matches)window.scrollTo(0,0);document.querySelector('meta[name="theme-color"]').content=s.theme==='dark'?'#20271f':'#f7f8f2';
}
function liveTripTXT(trip){
 const sources=Array.isArray(trip.sources)?trip.sources:[],bySource=new Map(sources.map(source=>[source.id,source]));
 const issues=rvTravelIssues(trip),validLegs=[];
 for(const day of trip.days||[])for(let index=1;index<(day.stops||[]).length;index++){const leg=rvIncomingLeg(trip,day,index);if(leg)validLegs.push(leg);}
 const queryISO=leg=>{const date=typeof leg.checkedAt==='string'?new Date(leg.checkedAt):null;return date&&!Number.isNaN(date.getTime())?date.toISOString():'查询时间未提供';};
 const checked=validLegs.map(queryISO).filter(value=>value!=='查询时间未提供').sort();
 const traffic=[`当前交通核对：${issues.conflicts.length}处时间不足，${issues.estimated}段有地图估计，${issues.pending}段待核对。`];
 for(const issue of issues.conflicts)traffic.push(`第${issue.dayIndex+1}天「${issue.previous.title}」→「${issue.node.title}」：${issue.message}`);
 if(checked.length)traffic.push(`有效估计的查询时间范围：${checked[0]}${checked.at(-1)!==checked[0]?' 至 '+checked.at(-1):''}`);
 if(issues.estimated)traffic.push('地图耗时仅为查询时估计，不保证出行当天交通；景区内移动与排队未计入。');
 if(issues.pending)traffic.push('未取得当前有效估计的路段仍待核对；预留间隔不代表实际交通耗时。');
 if(trip.backendWarningsStale)traffic.push('行程已修改，旧编排提醒已过期；本清单仅列当前可判断的交通问题。');
 else if(Array.isArray(trip.backendWarnings)){const warnings=trip.backendWarnings.filter(value=>typeof value==='string'&&value.trim());if(warnings.length)traffic.push('编排返回的提醒：',...warnings.map(value=>'· '+value));}
 const days=(trip.days||[]).map((day,dayIndex)=>{
  const rows=(day.stops||[]).map((node,index)=>{
   const parts=[];
   if(index){const previous=day.stops[index-1],leg=rvIncomingLeg(trip,day,index);parts.push(`交通：「${previous.title}」→「${node.title}」`);if(leg){parts.push(`估计${rvTravelMode(leg.mode)}${leg.durationMinutes}分钟；查询于 ${queryISO(leg)}。`,`范围：仅为查询时估计，不保证出行当天交通；景区内移动与排队未计入。`);const conflict=rvTravelConflict(previous,node,leg);if(conflict)parts.push('提醒：'+conflict);}else parts.push('交通待核对：没有当前有效的地图估计，预留间隔不代表实际耗时。');}
   const refs=(node.sourceIds||[]).map(id=>{const source=bySource.get(id);return source?`${source.title}${source.author?' / '+source.author:''}`:`${id}（来源详情未提供）`;});
   parts.push(`${node.time||'时间待定'} ${node.title} / ${node.duration||'待定'}分钟${node.locked?' / 固定':''}${node.locationStatus==='pending'?' / 地点待定':''}`,`备注：${node.notes||''}`,`出处：${refs.join('；')||'未附加攻略出处'}`);
   return parts.join('\n');
  });
  return `${dayLabel(dayIndex)} ${day.date||'日期待定'} ${day.name||''}\n`+rows.join('\n\n');
 });
 const references=sources.map(source=>`${source.title||'未命名攻略'} / ${source.author||'作者未提供'} / ${source.date||'日期未提供'}\n原帖：${LiveAPI.sourceURL(source.url)||'原帖链接未提供'}`);
 return [`MY PLAN 联网旅行规划`,trip.title||'我的旅行',trip.undated?'日期待定':trip.date||'日期待定','',traffic.join('\n'),'',days.join('\n\n'),'','参考来源',references.join('\n\n')||'暂无攻略来源','','预算（待核对）',JSON.stringify(trip.budget||{}),'准备清单',JSON.stringify(trip.preparation||{})].join('\n');
}
function exportTrip(type){const data={liveResearch:true,trip:s.trip};const text=type==='json'?JSON.stringify(data,null,2):liveTripTXT(s.trip);const url=URL.createObjectURL(new Blob([text],{type:type==='json'?'application/json;charset=utf-8':'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`MY_PLAN-旅行行程.${type}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);sheetError='';if(currentLayer())currentLayer().downloaded=true;}

function act(action,el){const id=el?.dataset.id,layer=currentLayer();sheetError='';
if(action==='download-evidence')return exportLiveEvidence();
if(action==='edit-plan-conditions')return route('create');
if(action==='reconnect-live')return connectLive();
if(action==='resume-research'){if(!s.research?.jobId)return startResearch();appError='';s.research.status='running';s.screen='search';researchController?.abort();researchController=new AbortController();persist();render();return advanceResearch();}
if(action==='search-city')return startResearch();
if(action==='resume-discovery'){if(s.discovery.liveResearch)return route('discover');return route('search');}
if(action==='discovery-category'){s.discovery.category=el.dataset.value;s.discovery.query='';persist();return render(true);}
if(action==='filter-candidates'){persist();return render();}
if(action==='clear-filter'){s.discovery.query='';persist();return render();}
if(action==='toggle-wish'){if(!wishById(id))return;if(s.discovery.selected[id])delete s.discovery.selected[id];else s.discovery.selected[id]={priority:'want'};persist();return render();}
if(action==='remove-wish'){delete s.discovery.selected[id];persist();return render();}
if(action==='priority-wish'){if(s.discovery.selected[id])s.discovery.selected[id].priority=s.discovery.selected[id].priority==='must'?'want':'must';persist();return render();}
if(action==='wish-detail')return openLayer('wish-detail',id);
if(action==='open-discovery-source')return openLayer('discovery-source',id);
if(action==='discovery-sources')return openLayer('discovery-sources');
if(action==='add-wish')return openLayer('add-wish',null,{title:'',category:s.discovery.category||'sights',duration:60});
if(action==='commit-custom-wish'){if(!String(layer.title||'').trim()){sheetError='先写下想去或想吃的内容。';return render();}const duration=Number(layer.duration);if(!Number.isInteger(duration)||duration<15||duration>480){sheetError='停留时间请填15～480分钟。';return render();}const item={id:'custom-'+Date.now().toString(36),title:layer.title.trim(),category:layer.category,region:'区域待确认',description:'由你手动补充的旅行内容',duration,sourceIds:[],photo:null,sourceType:'manual',notes:''};s.discovery.custom.push(item);s.discovery.selected[item.id]={priority:'want'};layers.pop();persist();return render();}
if(action==='to-basket')return route('basket');
if(action==='back-basket')return route('basket');
if(action==='back-discovery'){if(!s.discovery.researched)return route('search');return route('discover');}
if(action==='to-conditions'){const error=Discovery.validateSelection(s.discovery);if(error){appError=error;return render();}s.conditionsExpanded=false;s.form.destination=s.discovery.liveResearch?.city||s.discovery.city;return route('create');}
if(action==='home'){if(s.screen==='create')return route('basket');if(s.screen==='basket')return route('discover');if(s.screen==='discover')return route('search');return route('home');}if(action==='leave-progress')return route('home');
if(action==='new-trip'){if(s.job?.status==='running')return route('progress');s.discovery=Discovery.initial();s.research=null;s.form={...Model.fresh().form,prompt:'',destination:'',date:'',undated:true,arrival:'',returnTime:'',hotel:''};return route('search');}if(action==='new-from-trip'||action==='review-wishes'){restoreTripWishes();return route('basket');}
if(action==='open-trip'){s.tab='overview';return route('detail');}
if(action==='open-archive'){const chosen=s.otherTrips.find(x=>x.trip.id===id);if(!chosen)return;const copy=Model.clone(chosen);s.otherTrips=s.otherTrips.filter(x=>x.trip.id!==id);archiveCurrent();s.trip=copy.trip;s.editor=copy.editor;s.history=copy.history||[];s.lastMutation=copy.lastMutation||'';s.form={...Model.fresh().form,...copy.trip.creationForm,days:copy.trip.days.length,undated:copy.trip.undated,date:copy.trip.date||Model.fresh().form.date,...copy.trip.constraints};s.proposal=null;if(s.job?.resultId===copy.trip.id)s.job=null;s.tab='overview';s.activeDay=0;s.selectedId=null;return route('detail');}
if(action==='resume-editor'){s.screen='detail';layers=[];openLayer('edit',s.editor?.id);return;}
if(action==='toggle-conditions'){s.conditionsExpanded=!s.conditionsExpanded;persist();return render();}
if(action==='generate')return startJob();
if(action==='resume-job'||action==='retry-job'){if(!s.job)return;appError='';if(s.job.resumable||s.job.status==='paused'||s.job.status==='running'){if(!s.job.jobId){s.job=null;return startJob();}s.job.status='running';s.screen='progress';planController?.abort();planController=new AbortController();persist();render(true);return runJob();}s.job=null;return startJob();}
if(action==='cancel-job'){planController?.abort();if(s.job){s.job.status='paused';s.job.resumable=!!s.job.jobId;}return route('home');}
if(action==='tab'){s.tab=el.dataset.value;layers=[];persist();render(true);document.getElementById('tab-'+s.tab)?.focus({preventScroll:true});return;}
if(action==='day'||action==='day-overview'){s.activeDay=Number(el.dataset.index);s.selectedId=s.trip.days[s.activeDay].stops[0]?.id||null;s.mapZoom=1;if(action==='day-overview')s.tab='itinerary';persist();return render(true);}
if(action==='view'){s.view=el.dataset.value;persist();return render();}
if(action==='photo-prev'||action==='photo-next'){const track=document.querySelector('.rv-photo-track');if(!track)return;track.scrollBy({left:(track.firstElementChild.offsetWidth+12)*(action==='photo-next'?1:-1),behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});return;}
if(action==='node'){const n=findNode(id);if(n){s.selectedId=id;s.activeDay=n.dayIndex;persist();}return openLayer('node',id);}
if(action==='edit')return startEditor(id);
if(action==='add'){if(el.dataset.index)s.activeDay=Number(el.dataset.index);return startEditor('',true);}
if(action==='commit-editor')return routeMutation(()=>Model.commitEditor(s),'安排已保存');
if(action==='keep-edit'){layer.discard=false;return render();}
if(action==='keep-original-edit'){const i=layers.findIndex(x=>x.type==='edit');layers=i>=0?layers.slice(0,i+1):[{type:'edit',id:s.editor?.id}];return render();}
if(action==='switch-edit'){const target={id:layer.id,isNew:layer.isNew};s.editor=null;layers=[];return startEditor(target.id,target.isNew);}
if(action==='discard-edit')return closeLayer(true);
if(action==='node-menu')return openLayer('node-menu',id);
if(action==='remove')return routeMutation(()=>Model.removeStop(s,id),'已移除这一站');
if(action==='move'){const n=findNode(id);return openLayer('move',id,{targetDay:n.dayIndex,targetTime:n.time});}
if(action==='commit-move')return routeMutation(()=>Model.moveStop(s,layer.id,Number(layer.targetDay),0,layer.targetTime),'安排已移动，相邻交通待核对');
if(action==='commit-manual-place'){const place=String(layer.place||'').trim();if(!place){sheetError='请填写实际地点名称，或先保留原安排。';return render();}const n=findNode(layer.id);const before=routeEvidenceSignatures(s.trip);Model.snapshot(s);const node=s.trip.days[n.dayIndex].stops.find(x=>x.id===n.id);node.title=place;node.lng=null;node.lat=null;node.photo=null;node.liveImage=null;node.image=null;node.sourceIds=[];node.sourceRefs=[];node.verification=null;node.locationStatus='manual';node.pending=false;node.locationNote='用户手动填写的地点，坐标、营业与路线未核对。';node.manuallyEdited=true;s.trip.days[n.dayIndex].routeDirty=true;s.trip.version++;invalidateRouteEvidence(before,s.trip,[n.dayIndex]);layers=[];notice('已保存手动地点，位置和交通待核对');return render();}
if(action==='confirm'){const n=findNode(id);if(!n)return;return openLayer('confirm',id,{place:n.experiencePlace||''});}
if(action==='commit-experience-place'){const place=String(layer.place||'').trim();if(!place){sheetError='请填写地点，或先保留待定。';return render();}const n=findNode(layer.id);const before=routeEvidenceSignatures(s.trip);Model.snapshot(s);const node=s.trip.days[n.dayIndex].stops.find(x=>x.id===n.id);node.experiencePlace=place;node.locationStatus='manual';node.lng=null;node.lat=null;node.photo=null;node.liveImage=null;node.image=null;node.sourceIds=[];node.sourceRefs=[];node.verification=null;node.locationNote='体验地点由你手动指定，坐标、营业与路线未核对。';node.notes=(node.notes||'')+'\n手动地点：'+place;node.manuallyEdited=true;s.trip.version++;invalidateRouteEvidence(before,s.trip,[n.dayIndex]);layers=[];notice('已记下手动体验地点，实际位置待核对');return render();}
if(action==='locate'){const n=findNode(id);s.activeDay=n.dayIndex;s.selectedId=id;s.tab='itinerary';s.view='map';layers=[];persist();return render(true);}
if(action==='map-node'){s.selectedId=id;persist();return render();}
if(action==='map-list'||action==='source-node'){const n=findNode(id);if(!n)return;s.activeDay=n.dayIndex;s.selectedId=id;s.tab='itinerary';s.view='list';s.focusNode=id;if(action==='source-node'){openLayer('node',id);return;}layers=[];persist();return render();}
if(action==='zoom-in'||action==='zoom-out'||action==='zoom-reset'){s.mapZoom=action==='zoom-reset'?1:Math.min(1.6,Math.max(.8,(s.mapZoom||1)+(action==='zoom-in'?.2:-.2)));return render();}
if(action==='open-source')return openLayer('source',id);
if(action==='sources')return openLayer('sources');
if(action==='ai'){if(el.dataset.index)s.activeDay=Number(el.dataset.index);return openLayer('ai',null,{scope:'day',prompt:''});}
if(action==='ai-preset'){layer.prompt=el.dataset.value;return render();}
if(action==='preview-ai'){const result=Model.makeProposal(s,layer.prompt||'',layer.scope||'day');if(result.error){sheetError=result.error;return render();}s.proposal=result.proposal;persist();return openLayer('ai-preview');}
if(action==='apply-ai')return routeMutation(()=>Model.applyProposal(s),'已应用建议');
if(action==='discard-ai'){s.proposal=null;layers=[];persist();return render();}
if(action==='undo')return mutation(Model.undo(s),'已撤销上一次修改');
if(action==='dismiss-notice'){s.lastMutation='';persist();return render();}
if(action==='budget')return openLayer('budget',null,{budget:Model.clone(s.trip.budget)});
if(action==='commit-budget'){Model.snapshot(s);s.trip.budget=Model.clone(layer.budget);s.trip.version++;layers=[];notice('预算已保存');return render();}
if(action==='weather')return openLayer('weather');
if(action==='prep'){Model.snapshot(s);s.trip.preparation[el.dataset.key]=!s.trip.preparation[el.dataset.key];s.trip.version++;s.lastMutation='准备清单已保存';persist();return render();}
if(action==='menu'||action==='conditions'||action==='export')return openLayer(action);
if(action==='download-txt'||action==='download-json'){exportTrip(action==='download-txt'?'txt':'json');return;}
if(action==='close-sheet')return closeLayer();
if(action==='retry-save'){persist();return render();}
if(action==='theme'){s.theme=el.dataset.value;persist();return render(true);}
if(action==='reopen'){researchController?.abort();planController?.abort();const result=Model.restore();if(!result.state){appError=result.error||'还没有保存的草稿。';return render();}s=result.state;s.otherTrips=s.otherTrips||[];seedRouteEvidence(s.trip);s.otherTrips.forEach(item=>seedRouteEvidence(item.trip));s.discovery=s.discovery||Discovery.initial();if(s.research?.status==='running')s.research.status='paused';if(s.job?.status==='running')s.job.status='paused';s.screen='home';layers=[];s.saveStatus='saved';return render(true);}
}
document.getElementById('app').addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled||(layers.length&&!el.closest('.sheet-layer')))return;act(el.dataset.action,el);});
document.getElementById('app').addEventListener('input',event=>{const el=event.target;if(el.dataset.discovery){s.discovery[el.dataset.discovery]=el.value;persist();}if(el.dataset.form){s.form[el.dataset.form]=el.type==='checkbox'?el.checked:el.dataset.form==='days'?Number(el.value):el.value;persist();}if(el.dataset.edit&&s.editor){s.editor[el.dataset.edit]=el.type==='checkbox'?el.checked:el.value;persist();}if(el.dataset.layer&&currentLayer())currentLayer()[el.dataset.layer]=el.value;if(el.dataset.budget){currentLayer().budget[el.dataset.budget]=Math.max(0,Math.min(100000,Number(el.value)||0));document.querySelector('#budget-sum').textContent=money(Object.values(currentLayer().budget).reduce((a,b)=>a+Number(b||0),0));}});
document.getElementById('app').addEventListener('change',event=>{const el=event.target;if(el.dataset.form==='undated'){persist();render();}if(el.tagName==='SELECT'&&el.dataset.layer)currentLayer()[el.dataset.layer]=el.value;});
document.addEventListener('keydown',event=>{if(layers.length){if(event.key==='Escape'){event.preventDefault();return closeLayer();}if(event.key==='Tab'){const sheet=document.querySelector('.sheet'),items=[...sheet.querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled&&x.getClientRects().length),first=items[0],last=items[items.length-1];if(!sheet.contains(document.activeElement)||(event.shiftKey&&document.activeElement===first)||(!event.shiftKey&&document.activeElement===last)){event.preventDefault();(event.shiftKey?last:first)?.focus();}}return;}if(event.target.matches('.main-tabs [role="tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const value=event.key==='Home'?'overview':event.key==='End'?'itinerary':s.tab==='overview'?'itinerary':'overview';act('tab',{dataset:{value}});}if(event.target.matches('svg [role="button"]')&&['Enter',' '].includes(event.key)){event.preventDefault();act(event.target.dataset.action,event.target);}});
document.addEventListener('focusout',event=>{const el=event.target;if(el.dataset?.edit&&currentLayer()?.type==='edit')currentLayer().focus={id:el.id,start:el.selectionStart||0,end:el.selectionEnd||0};});
document.addEventListener('focusin',event=>{const sheet=document.querySelector('.sheet');if(sheet&&!sheet.contains(event.target))sheet.querySelector('button')?.focus({preventScroll:true});});
history.scrollRestoration='manual';render();connectLive();
